function populateLanguages(){
  for(const [code,name] of languageNames){if(code==='en')continue;const option=document.createElement('option');option.value=code;option.textContent=name;languagePicker.append(option);}
}
populateLanguages();
function showLanguageChoice(language){languagePicker.value=languageNames.some(([code])=>code===language)?language:'en';}
function excludedFromTranslation(node){return !node.parentElement || !!node.parentElement.closest('script,style,option,.avatar,#device-message,#device-language-note,.form-message');}
function restoreEnglish(){for(const [node,entry] of translations){if(node.isConnected && node.nodeValue===entry.translated)node.nodeValue=entry.original;}translations.clear();}
async function translateInterface(root,run){
  if(!deviceTranslator && !languageDetector)return;
  const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);const nodes=[];let node;
  while((node=walker.nextNode())) if(node.nodeValue.trim() && !excludedFromTranslation(node)) nodes.push(node);
  for(const n of nodes){
    if(run!==translationRun || (!deviceTranslator && !languageDetector))return;
    const old=translations.get(n);if(old && n.nodeValue===old.translated)continue;
    const original=n.nodeValue;if(!original.trim())continue;
    try{
      const content=!!n.parentElement.closest('.post,#circles-list,#blocked-list,#settings-user');
      let source='en';
      if(content){if(!languageDetector)continue;const result=await languageDetector.detect(original);const best=result?.[0];if(!best || best.detectedLanguage==='und' || best.confidence<0.5)continue;source=best.detectedLanguage.split('-')[0];}
      if(source===deviceTarget.split('-')[0])continue;
      let engine=source==='en'?deviceTranslator:translators.get(source);
      if(!engine){const options={sourceLanguage:source,targetLanguage:deviceTarget};if(await window.Translator.availability(options)!=='available')continue;engine=await window.Translator.create(options);translators.set(source,engine);}
      if(!engine || !engine.translate)continue;const translated=await engine.translate(original);if(run===translationRun && n.isConnected && n.nodeValue===original){translations.set(n,{original,translated});n.nodeValue=translated;}}catch{}
  }
}
async function setDeviceLanguage(language,{restore=false}={}){
  const run=++translationRun;deviceTranslator?.destroy?.();deviceTranslator=null;languageDetector?.destroy?.();languageDetector=null;for(const engine of translators.values())engine.destroy?.();translators.clear();deviceTarget=language;restoreEnglish();document.documentElement.lang='en';
  if(language==='en'){showLanguageChoice('en');deviceOptions.set('turboshot-device-language','en');message(deviceMessage,'');if(window.LanguageDetector && window.Translator)try{if(await window.LanguageDetector.availability()==='available'){languageDetector=await window.LanguageDetector.create();await translateInterface(document.body,run);}}catch{}return;}
  const opts={sourceLanguage:'en',targetLanguage:language};
  if(!window.Translator){showLanguageChoice('en');deviceOptions.set('turboshot-device-language','en');message(deviceMessage,'This browser cannot translate the app. You can use your browser’s page translation instead.');return;}
  try{
    const availability=await window.Translator.availability(opts);if(run!==translationRun)return;
    if(availability==='unavailable' || availability==null)throw new Error('unsupported');
    if(restore && availability!=='available'){showLanguageChoice('en');message(deviceMessage,'Select your language again to finish setting it up.');return;}
    message(deviceMessage,availability==='available'?'Changing language…':'Preparing your language. Your browser may download language files…');
    const translator=await window.Translator.create(opts);if(run!==translationRun){translator.destroy?.();return;}
    deviceTranslator=translator;if(window.LanguageDetector)try{if(await window.LanguageDetector.availability()==='available')languageDetector=await window.LanguageDetector.create();}catch{}showLanguageChoice(language);deviceOptions.set('turboshot-device-language',language);document.documentElement.lang=language;message(deviceMessage,'');
    await translateInterface(document.body,run);
  }catch{if(run===translationRun){showLanguageChoice('en');deviceOptions.set('turboshot-device-language','en');message(deviceMessage,'This language is not available in this browser. Try your browser’s page translation.');}}
}
languagePicker.addEventListener('change',e=>setDeviceLanguage(e.target.value));
const translationObserver=new MutationObserver(records=>{if(!deviceTranslator && !languageDetector)return;for(const record of records)for(const node of record.addedNodes)if(node.nodeType===1)translateInterface(node,translationRun);else if(node.nodeType===3 && node.parentElement && !excludedFromTranslation(node))translateInterface(node.parentElement,translationRun);});
translationObserver.observe(document.body,{childList:true,subtree:true});
const savedLanguage=deviceOptions.get('turboshot-device-language','en');if(savedLanguage!=='en')setDeviceLanguage(savedLanguage,{restore:true});else if(window.Translator && window.LanguageDetector)setDeviceLanguage('en',{restore:true});
async function init() {
  const hash = new URLSearchParams(location.hash.slice(1));
  const kind = hash.has('reset') ? 'reset' : hash.has('verify') ? 'verify' : '';
  if (kind) { linkTicket = hash.get(kind); history.replaceState(null,'',location.pathname + location.search); showAuth(kind); }
  if (apiBase) {
    if (session) { try { me = (await api('me',{},'GET')).user; } catch { clearSession(); } }
  }
  updateAccount(); await loadFeed();
}
init();




